// Send LIST command or retr <file_name> to Server

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8083
#define MAX 1024

int main() {
    int sock;
    struct sockaddr_in server_addr;

    char command[MAX];
    char buffer[MAX];

    // Creating SOCKET
    sock = socket(AF_INET, SOCK_STREAM, 0);

    // Server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    // Connect
    connect(sock, (struct sockaddr *)&server_addr,
            sizeof(server_addr));

    printf("Connected to Server!\n");

    // Send LIST command
    printf("Enter command (LIST / retr <file_name>): ");
    fgets(command, sizeof(command), stdin);

    // Remove newline
    command[strcspn(command, "\n")] = '\0';

    send(sock, command, strlen(command) + 1, 0);

    // Receive response
    printf("\nServer Response:\n");

    int bytes;

    while ((bytes = recv(sock, buffer,
                         sizeof(buffer) - 1, 0)) > 0) {

        buffer[bytes] = '\0';

        printf("%s", buffer);

        // Stop after end marker
        if (strstr(buffer, "---END OF FILE---") != NULL)
            break;

        // LIST response normally arrives as one message
        if (strcmp(command, "LIST") == 0)
            break;
    }

    printf("\n");

    close(sock);

    return 0;
}
